INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121714024X02120250521_014',
        '2025-05-21',
        217,
        '参議院',
        '議院運営委員会',
        '阿達雅志',
        '自由民主党',
        '自由民主党',
        '○副大臣（阿達雅志君）　公害等調整委員会委員都築政則君及び野中智子君の両君は本年六月三十日に任期満了となりますが、都築政則君の後任として中村也寸志君を、野中智子君の後任として大瀧敦子君を任命いたしたいので、公害等調整委員会設置法第七条第一項の規定により、両議院の同意を求めるため本件を提出いたしました。  　次に、日本放送協会経営委員会委員榊原一夫君、大草透君、明石伸子君、藤本雅彦君及び村田晃嗣君の五君は本年六月十九日に任期満了となりますが、明石伸子君の後任として岡田美弥子君を、村田晃嗣君の後任として田渕正朗君を任命することとし、榊原一夫君、大草透君及び藤本雅彦君を再任いたしたいので、放送法第三十一条第一項の規定により、両議院の同意を求めるため本件を提出いたしました。  　何とぞ、御審議の上、速やかに御同意賜りますようお願いいたします。',
        'https://kokkai.ndl.go.jp/txt/121714024X02120250521/14',
        '2025-06-09T23:21:38.126197'
      );
