INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121714024X02120250521_025',
        '2025-05-21',
        217,
        '参議院',
        '議院運営委員会',
        '牧野たかお',
        '自由民主党',
        '自由民主党',
        '○委員長（牧野たかお君）　次に、本日の本会議の議事に関する件を議題といたします。  　事務総長の説明を求めます。',
        'https://kokkai.ndl.go.jp/txt/121714024X02120250521/25',
        '2025-06-09T23:21:38.126312'
