INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121714575X00320250521_001',
        '2025-05-21',
        217,
        '参議院',
        '政治改革に関する特別委員会',
        '豊田俊郎',
        '自由民主党',
        '自由民主党',
        '○委員長（豊田俊郎君）　ただいまから政治改革に関する特別委員会を開会いたします。  　委員の異動について御報告申し上げます。  　昨日までに、高橋次郎君、川合孝典君、山本啓介君、越智俊之君、こやり隆史君、清水真人君及び上月良祐君が委員を辞任され、その補欠として矢倉克夫君、上田清司君、白坂亜紀君、船橋利実君、星北斗君、臼井正一君及び三宅伸吾君が選任されました。  　　　　─────────────',
        'https://kokkai.ndl.go.jp/txt/121714575X00320250521/1',
        '2025-06-09T23:21:38.126373'
      );
INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121714575X00320250521_002',
