INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121724293X00220250521_035',
        '2025-05-21',
        217,
        '両院',
        '国家基本政策委員会合同審査会',
        '石破茂',
        '自由民主党・無所属の会',
        '自由民主党・無所属の会',
        '○内閣総理大臣（石破茂君）　私はそうだと思っています。  　そのときに、基準をどう考えるかということで、ウインカーは昔は赤でしたよね。オレンジになったの最近の話、最近というか、二十年ぐらい前かな。  　アメリカと日本と、代表御存じのとおり、交通事情が違いますので、交通事故は、アメリカの場合には自動車対自動車だ、日本の場合には自動車対歩行者だということがございます。  　そうすると、今おっしゃったアメリカで造った日本メーカーの車を、アメリカの車が売れないのは、やれ左ハンドルだとか、でかいとか、燃費が良くないとか、悪口ばっかり言っても仕方ないけど、そういう理由もありますが、もう一つはディーラーの数が決定的に少ないということでございます。それを活用するということはあり得るだろう。  　しかし、安全基準については、私は、日本の国民、消費者、歩行者、ドライバーも含めて、これを犠牲にするということはあってはならないが、どうやってアメリカで造った日本の車、言い方は難しいですけど、それを販売するかということも私は手法の一つとしてあり得ることだと考えております。（拍手）',
        'https://kokkai.ndl.go.jp/txt/121724293X00220250521/35',
        '2025-06-09T23:21:38.126611'
      );
INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
