INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121704127X00220250519_140',
        '2025-05-19',
        217,
        '衆議院',
        '決算行政監視委員会',
        '河村たかし',
        '日本保守党',
        '日本保守党',
        '○河村委員　保守党といたしましては、反対ということでございます。  　理由は、本当にこれは経済の考え方を変えないと。民間は金が物すごく余っておるんですよ、今。借りる人がいないわけです、お金を。  　すごく余っておるのに、相変わらず、この国会か何か知りませんけれども、上級国民がみんな集まって、自分らの、会社でいうと総務部の金だけ言っておるわけです。減税でもそうですよ。総務部なんかに金があるわけがないですよ、会社には。  　営業本部に余っていて、実は、今の国の状況でいうと、銀行に物すごく余っておるわけです。それがたまってきたものが日銀の五百三十兆です。そちらのお金と両方一緒に、どうやって使っていくか。  　ただ、財政法四条というのがありまして、それで、何か偉い人は、民間の金を使ってはいかぬと書いてあるわけです。ただ、例外がありますけれども、公共事業と、それから特例債の場合は。  　だから、もうその辺をどうするかということを考えて日本国全体の経済運営を考えないと、産業の力が落ちちゃうでいかぬわ、このままだと。ＧＡＦＡに負けちゃったじゃないですか、加藤さん。  　ということで、そんな前提に立っておる予算は、当然賛成できません。  　以上です。',
        'https://kokkai.ndl.go.jp/txt/121704127X00220250519/140',
        '2025-06-09T23:21:38.127722'
      );
