INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121714024X01920250514_004',
        '2025-05-14',
        217,
        '参議院',
        '議院運営委員会',
        '小林史武',
        '',
        '',
        '○事務総長（小林史武君）　立法事務費の交付を受ける会派の認定は、国会における各会派に対する立法事務費の交付に関する法律の規定により、議院運営委員会の議決によって決定することになっております。  　今回、新たに「令月会」から立法事務費の交付を受ける会派としての所定の届出がございましたので、本委員会の認定について御決定をお願いいたします。',
        'https://kokkai.ndl.go.jp/txt/121714024X01920250514/4',
        '2025-06-09T23:21:38.128026'
      );
