INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121705261X02220250512_021',
        '2025-05-12',
        217,
        '衆議院',
        '予算委員会',
        '長妻昭',
        '立憲民主党・無所属',
        '立憲民主党・無所属',
        '○長妻委員　おはようございます。  　総理、いろいろお疲れだと思いますけれども、よろしくお願いをいたします。  　今日は年金中心に質問しますけれども、まずは、一部報道にあります首相の金などについて、確認だけさせていただきたいというふうに思います。  　まず、石破茂政経懇話会という石破さんの政治団体の代表に、一時的ですけれども、下根貴弘さんがなっておられるんですが、これはなぜですか。',
        'https://kokkai.ndl.go.jp/txt/121705261X02220250512/21',
        '2025-06-09T23:21:38.128495'
      );
INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121705261X02220250512_022',
        '2025-05-12',
        217,
        '衆議院',
        '予算委員会',
        '石破茂',
        '自由民主党・無所属の会',
        '自由民主党・無所属の会',
        '○石破内閣総理大臣　石破茂政経懇話会の代表者の方が二〇〇二年にお亡くなりになりました。私どもの会計責任者が、この報道にございます親子のお二人のうち、お父様に御相談をしたところ、それでは息子が代表者になろうかというふうなお申出があったので、この方が代表者になられたというふうに承知をいたしております。',
        'https://kokkai.ndl.go.jp/txt/121705261X02220250512/22',
        '2025-06-09T23:21:38.128504'
      );
INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
