INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121705261X02220250512_149',
        '2025-05-12',
        217,
        '衆議院',
        '予算委員会',
        '安住淳',
        '立憲民主党・無所属',
        '立憲民主党・無所属',
        '○安住委員長　これにて福重君の質疑は終了いたしました。  　次に、高井崇志君。',
        'https://kokkai.ndl.go.jp/txt/121705261X02220250512/149',
        '2025-06-09T23:21:38.129830'
