INSERT OR REPLACE INTO speeches (id, date, session, house, committee, speaker, party, party_normalized, text, url, created_at) VALUES (
        '121705261X02220250512_166',
        '2025-05-12',
        217,
        '衆議院',
        '予算委員会',
        '辰巳孝太郎',
        '日本共産党',
        '日本共産党',
        '○辰巳委員　五％減税、これは是非、国民の暮らしを守るためにやろう、やるべきだという提案をさせていただいて、私の質問を終わります。  　以上です。',
        'https://kokkai.ndl.go.jp/txt/121705261X02220250512/166',
